{
  "query": "select:WebSearch,WebFetch",
  "max_results": 2
}

{
  "query": "3I/ATLAS solar wind interaction ion tail arXiv",
  "mode": "extended"
}

{
  "query": "XRISM ATel 3I/ATLAS X-ray detection charge exchange",
  "mode": "standard"
}

{
  "url": "https://www.astronomerstelegram.org/?read=17523",
  "prompt": "Give the full text of this ATel: title, authors, date, and every quantitative value (fluxes, energies, observation dates, distances, solar wind values)."
}

{
  "url": "https://arxiv.org/abs/2510.13222",
  "prompt": "Give authors, title, submission date, journal ref if any, and the full abstract. List any solar wind values (speed, density, IMF, etc.) mentioned."
}

{
  "url": "https://arxiv.org/pdf/2510.13222",
  "prompt": "What solar wind speeds or other solar wind parameters (range, assumed values) does the Tailcatcher model use? Quote exact numbers, heliocentric distances, and dates of tail crossings, and any discussion of PUI/pickup ions or CMEs."
}

{
  "query": "3I/ATLAS Europa Clipper ion tail crossing results solar wind observation 2026",
  "mode": "extended"
}

{
  "command": "mkdir -p /tmp/claude-1000/-mnt-c-Users-cabot-OneDrive-Documents-Research-Cambridge-X3I/c4794a53-4881-4aa9-8b9b-7c033457fa8b/scratchpad/pdfs && which pdftotext && pdftotext /home/scabot/.claude/projects/-mnt-c-Users-cabot-OneDrive-Documents-Research-Cambridge-X3I/c4794a53-4881-4aa9-8b9b-7c033457fa8b/tool-results/webfetch-1792192247085-y5z4gd.pdf - | head -200",
  "description": "Extract text from the downloaded ion tail paper PDF"
}

{
  "command": "python3 -I -c \"import pypdf\" 2>&1; python3 -I -c \"import fitz\" 2>&1; which mutool qpdf gs 2>&1",
  "description": "Check for PDF text extraction tools"
}

{
  "url": "https://arxiv.org/abs/2609.05393",
  "prompt": "Give authors, title, submission date, journal ref, full abstract. Mention any solar wind values or tail kinematics (ion velocities, tail direction, aberration angle) with dates."
}

{
  "query": "3I/ATLAS solar wind model ENLIL OR EUHFORIA OR HUXt OR SWMF conditions perihelion",
  "mode": "extended"
}

{
  "query": "\"3I/ATLAS\" Deca hybrid simulation solar wind interaction",
  "mode": "extended"
}

{
  "query": "\"3I/ATLAS\" tail disconnection event CME",
  "mode": "extended"
}

{
  "url": "https://watchers.news/2025/09/24/cme-forecast-to-strike-interstellar-comet-3i-atlas-on-september-24-25/",
  "prompt": "Extract all quantitative details: CME launch time, ENLIL model source, predicted arrival at the comet, comet heliocentric distance, CME speed, solar wind density/speed values, who made the forecast (e.g., spaceweather.com, NASA CCMC), and any follow-up observations."
}

{
  "url": "https://www.iflscience.com/interstellar-comet-3iatlas-is-about-to-be-hit-by-a-coronal-mass-ejection-what-will-happen-next-80946",
  "prompt": "Extract all quantitative details: CME launch time, model used (ENLIL), predicted arrival time at comet, comet heliocentric distance, CME speed, any solar wind values, who made the forecast, and any quoted scientists."
}
